sql.if:


AND l.id IN (
    SELECT l.id FROM inv_stock_log l WHERE true

    AND (upper(l.doc_no) LIKE #{keywordCode}
         OR upper(l.doc_no) IN #{code})
    UNION
    SELECT l.id FROM inv_stock_log l WHERE true

    AND l.dye_lot ILIKE #{keywordContains}
    UNION
    SELECT l.id FROM inv_stock_log l WHERE true

    AND l.material_sku_id IN (
        SELECT k.id FROM bas_material_sku k WHERE upper(k.code) LIKE #{keywordCode}
        OR upper(k.code) IN #{code}
        UNION
        SELECT k.id FROM bas_material m JOIN bas_material_sku k ON k.material_id = m.id
        WHERE m.name ILIKE #{keywordContains}
        OR upper(m.code) IN #{code}
    )
)

mapper.select:
SELECT * FROM ( SELECT v.material_sku_id, k.code AS sku_code, COALESCE(SUM(v.change_qty) FILTER (WHERE NOT v.in_period), 0) AS opening_qty, COALESCE(SUM(v.change_qty) FILTER (WHERE v.in_period AND v.inward), 0) AS in_qty, COALESCE(-SUM(v.change_qty) FILTER (WHERE v.in_period AND NOT v.inward), 0) AS out_qty, SUM(v.change_qty) AS closing_qty, COALESCE(SUM(v.change_qty) FILTER (WHERE v.in_period AND v.inward AND v.change_type = 'PURCHASE_IN'), 0) AS purchase_in, COALESCE(SUM(v.change_qty) FILTER (WHERE v.in_period AND v.inward AND v.change_type = 'RETURN_IN'), 0) AS return_in, COALESCE(SUM(v.change_qty) FILTER (WHERE v.in_period AND v.inward AND v.change_type = 'OTHER_IN'), 0) AS other_in, COALESCE(SUM(v.change_qty) FILTER (WHERE v.in_period AND v.inward AND v.change_type = 'TRANSFER'), 0) AS transfer_in, COALESCE(SUM(v.change_qty) FILTER (WHERE v.in_period AND v.inward AND v.change_type = 'COUNT_GAIN'), 0) AS count_gain, COALESCE(SUM(v.change_qty) FILTER (WHERE v.in_period AND v.inward AND v.change_type = 'OPENING'), 0) AS opening_in, COALESCE(-SUM(v.change_qty) FILTER (WHERE v.in_period AND NOT v.inward AND v.change_type = 'ISSUE_OUT'), 0) AS issue_out, COALESCE(-SUM(v.change_qty) FILTER (WHERE v.in_period AND NOT v.inward AND v.change_type = 'PURCHASE_RETURN'), 0) AS purchase_return, COALESCE(-SUM(v.change_qty) FILTER (WHERE v.in_period AND NOT v.inward AND v.change_type = 'OTHER_OUT'), 0) AS other_out, COALESCE(-SUM(v.change_qty) FILTER (WHERE v.in_period AND NOT v.inward AND v.change_type = 'TRANSFER'), 0) AS transfer_out, COALESCE(-SUM(v.change_qty) FILTER (WHERE v.in_period AND NOT v.inward AND v.change_type = 'COUNT_LOSS'), 0) AS count_loss FROM ( SELECT l.material_sku_id, l.change_type, l.change_qty, l.biz_date >= #{q.bizDateFrom} AS in_period, (l.change_qty > 0) <> (l.reversal_of_log_id IS NOT NULL) AS inward FROM inv_stock_log l JOIN bas_warehouse w ON w.id = l.warehouse_id WHERE w.type IN ('MATERIAL', 'FACTORY') AND l.biz_date <= #{q.bizDateTo} AND w.type = #{q.warehouseType} AND l.warehouse_id = #{q.warehouseId}
AND l.material_sku_id IN ( SELECT mk.id FROM bas_material_sku mk WHERE upper(mk.code) LIKE #{keywordCode} OR upper(mk.code) IN #{code} UNION SELECT mk.id FROM bas_material_sku mk JOIN bas_material mm ON mm.id = mk.material_id WHERE upper(mm.code) LIKE #{keywordCode} OR mm.name ILIKE #{keywordContains} OR upper(mm.code) IN #{code} )
) v JOIN bas_material_sku k ON k.id = v.material_sku_id GROUP BY v.material_sku_id, k.code ) t WHERE opening_qty <> 0 OR in_qty <> 0 OR out_qty <> 0 OR closing_qty <> 0 ORDER BY sku_code, material_sku_id
